"""Check card numbers with the Luhn algorithm."""


def valid(number):
    """Return True if *number* passes the Luhn check, otherwise False.

    Spaces are ignored. After removing spaces, the value must contain at
    least two digits and nothing other than the digits 0 through 9.
    """
    if not isinstance(number, str):
        return False

    digits = number.replace(" ", "")
    if len(digits) < 2:
        return False
    for char in digits:
        if char < "0" or char > "9":
            return False

    total = 0
    for position, char in enumerate(reversed(digits)):
        digit = int(char)
        if position % 2 == 1:
            digit *= 2
            if digit > 9:
                digit -= 9
        total += digit

    return total % 10 == 0
